import { SubscriberStore } from "./solution";
import type { Subscriber } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function throwsRange(fn: () => unknown): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, "empty id rejected");
}
function throwsMessage(fn: () => unknown, expected: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof Error && error.message === expected, expected);
}

const v1: Subscriber[] = [
  { id: "a", name: "", email: "", active: true },
  { id: "b", name: "Bee", email: "b@test", active: false }
];
const v2: Subscriber[] = [{ id: "x", name: "Ex", email: "x@test", active: true }];
const store = new SubscriberStore(v1, v2);
v1[0].name = "mutated";
v2[0].id = "mutated";
deepEqual(store.list(), [
  { id: "a", name: "", email: "", active: true },
  { id: "b", name: "Bee", email: "b@test", active: false }
], "list reads cloned V1 in constructor order");

const listed1 = store.list();
const listed2 = store.list();
assert(listed1 !== listed2 && listed1[0] !== listed2[0], "list and entries are fresh");
listed1[0].name = "external";
assert(store.list()[0].name === "", "listed objects do not alias state");

const addedInput: Subscriber = { id: "n", name: "", email: "", active: false };
const added = store.add(addedInput);
assert(added !== addedInput, "add returns a fresh object");
addedInput.id = "changed";
added.id = "also-changed";
throwsMessage(() => store.add({ id: "n", name: "duplicate", email: "", active: true }), "duplicate subscriber");
assert(store.remove("n") === true && store.remove("n") === false, "remove affects V2 and reports existence");
assert(store.remove("a") === false, "V1 entries are not affected by V2 operations");

store.add({ id: "u", name: "before", email: "old", active: false });
const updateInput: Subscriber = { id: "u", name: "after", email: "", active: true };
const updated = store.update(updateInput);
assert(updated !== updateInput, "update returns a clone");
updateInput.name = "external";
updated.id = "external";
const updatedAgain = store.update({ id: "u", name: "final", email: "mail", active: false });
deepEqual(updatedAgain, { id: "u", name: "final", email: "mail", active: false }, "update remains keyed by stored id");
throwsMessage(() => store.update({ id: "missing", name: "", email: "", active: false }), "subscriber not found");

throwsRange(() => store.add({ id: "", name: "", email: "", active: false }));
throwsRange(() => store.update({ id: "", name: "", email: "", active: false }));
throwsRange(() => store.remove(""));
throwsMessage(() => new SubscriberStore([v1[0], { ...v1[0] }]), "duplicate subscriber");
throwsMessage(() => new SubscriberStore([], [{ id: "z", name: "", email: "", active: true }, { id: "z", name: "2", email: "", active: false }]), "duplicate subscriber");

